// Verifies X-Docflow-Signature: sha256=<hex> = HMAC-SHA256(secret, `${timestamp}.${body}`)
// using the secret returned once by POST /api/v1/settings/webhooks — see the
// sticky note above and docs/API.md for the full scheme.
//
// CAVEAT: this reconstructs the signed string by re-serializing the parsed JSON
// body, which is not guaranteed byte-identical to what Docflow actually signed.
// For production use, enable "Raw Body" in the Webhook node's options and verify
// against the raw buffer instead of re-serialized JSON.
const crypto = require('crypto');

const secret = $env.DOCFLOW_WEBHOOK_SECRET;
if (!secret) {
  throw new Error('DOCFLOW_WEBHOOK_SECRET is not set on this n8n instance');
}

const headers = $json.headers || {};
const timestamp = headers['x-docflow-timestamp'];
const providedSignature = headers['x-docflow-signature'] || '';
const body = JSON.stringify($json.body);

const expectedSignature = 'sha256=' + crypto
  .createHmac('sha256', secret)
  .update(`${timestamp}.${body}`)
  .digest('hex');

const signaturesMatch =
  providedSignature.length === expectedSignature.length &&
  crypto.timingSafeEqual(Buffer.from(expectedSignature), Buffer.from(providedSignature));

if (!signaturesMatch) {
  throw new Error('Docflow webhook signature verification failed');
}

return [{ json: $json.body }];
